import { resetError, updateLoader, useErrorContextValue, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { useCallback, useState, useMemo, useEffect, useRef } from 'react'
import { Container } from '../../../../../../components'
import ConfirmationModal from '../../../../../../components/ConfirmationModal'
import ShowSnackbar from '../../../../../../components/ShowNotification'
import Tabs from '../../../../../../components/Tabs'
import { ADDITIONAL_INFORMATION_REQUIRED, MANUAL_ORDER } from '../../../../../../constants/pkgCode'
import { downloadFile } from '../../../../../../helpers/mitraUtils/mitra-utility'
import { LANG_STRINGS } from '../../../../../../lang'
import OfflinePolicyContainer from '../../../../../CommonContainer/OfflinePolicyContainer'
import { OFFER_QUOTES_TABS } from '../../../constants'
import { useGetOfflineQuoteDetail, useOfflineQuoteAccept } from '../../../state/hooks/usePolicyState'
import OfflinePolicyQuote from '../../OfflinePolicyReviewForm/components/OfflinePolicyQuote'
import QuotesCard from '../components/QuotesCard'
import { OfferQuotesStyle } from './index.style'

function OfflineOfferQuotesContainer ({ match, history }) {
  const urlParams = useMemo(() => match?.params || {}, [match])
  const [selectedTab, setSelectedTab] = useState(OFFER_QUOTES_TABS[0])
  const [pageConfig, setPageConfig] = useState({
    isOfflineOrderDetail: true,
    quoteId: urlParams.quoteId
  })
  const [{ offlineQuoteDetailData = {} }, offlineQuoteDetailReq] = useGetOfflineQuoteDetail()
  const [{ offlineQuoteAcceptData }, offlineQuoteAcceptReq] = useOfflineQuoteAccept()
  const [
    {
      OFFLINE_QUOTE_DETAIL_LOADER, OFFLINE_QUOTE_ACCEPT_LOADER,
      CONVERT_DOC_TO_PDF_LOADER
    },
    dispatchLoader
  ] = useLoaderContextValue()
  const [{ offlineQuoteAcceptStatus, offlineQuoteDetailStatus }, dispatchError] = useErrorContextValue()
  const [showConfirmation, setConfirmation] = useState(false)
  const that = useRef({})

  useEffect(() => {
    if (OFFLINE_QUOTE_DETAIL_LOADER === undefined) {
      offlineQuoteDetailReq({
        quoteId: urlParams.quoteId
      })
    }
  }, [urlParams.quoteId, OFFLINE_QUOTE_DETAIL_LOADER, offlineQuoteDetailReq])

  useEffect(() => {
    function resetErrorKey (key) {
      dispatchError(resetError({
        [key]: undefined
      }))
    }
    if (offlineQuoteAcceptStatus === 'success') {
      ShowSnackbar.success({
        visible: true,
        text: LANG_STRINGS.quoteAccepted
      })
      let path = `/offline/detail/${urlParams.quoteId}`
      if (offlineQuoteAcceptData?.status === ADDITIONAL_INFORMATION_REQUIRED) {
        path = `/offline/quotes/additional/info/${urlParams.quoteId}`
      }
      setTimeout(() => {
        history.push(path)
      }, 100)
      resetErrorKey('offlineQuoteAcceptStatus')
    } else if (offlineQuoteAcceptStatus) {
      ShowSnackbar.error({
        visible: true,
        text: offlineQuoteAcceptStatus
      })
      resetErrorKey('offlineQuoteAcceptStatus')
    }

    if (offlineQuoteDetailStatus === 'success') {
      setPageConfig(pageConfig => ({
        ...pageConfig,
        isManualOrder: offlineQuoteDetailData.policy_details.protection_case === MANUAL_ORDER
      }))
      resetErrorKey('offlineQuoteDetailStatus')
    }

    // if (convertDocToPdfStatus === 'success') {
    //   history.push(
    //     `/custom-url?title=${LANG_STRINGS.orderDetails}&src=${convertDocToPdfData.url}`
    //   )
    //   resetErrorKey('convertDocToPdfStatus')
    // } else if (convertDocToPdfStatus) {
    //   ShowSnackbar.error({
    //     visible: true,
    //     text: convertDocToPdfStatus
    //   })
    //   resetErrorKey('convertDocToPdfStatus')
    // }
  }, [
    offlineQuoteAcceptStatus, offlineQuoteDetailStatus,
    offlineQuoteDetailData, dispatchError, urlParams.quoteId,
    history, offlineQuoteAcceptData
  ])

  useEffect(() => {
    return () => {
      dispatchLoader(updateLoader({
        OFFLINE_QUOTE_DETAIL_LOADER: undefined
      }))
    }
  }, [dispatchLoader])

  const handleTabClick = useCallback((tab) => {
    setSelectedTab(tab)
  }, [])

  const handleToggleConfirmationModal = useCallback((id) => {
    that.current.providerId = id
    setConfirmation(isConfirm => !isConfirm)
  }, [])

  const handleShowOfferQuote = useCallback((provider) => {
    downloadFile(provider.quotation_slip_url)
  }, [])

  const handleAgreeModal = useCallback(() => {
    offlineQuoteAcceptReq({
      quoteId: offlineQuoteDetailData.id,
      providerId: that.current.providerId
    })
    setConfirmation(false)
  }, [offlineQuoteAcceptReq, offlineQuoteDetailData.id])

  return (
    <Container
      title={LANG_STRINGS.orderDetails}
      loader={OFFLINE_QUOTE_DETAIL_LOADER || OFFLINE_QUOTE_ACCEPT_LOADER || CONVERT_DOC_TO_PDF_LOADER}
      hideBottomTabs
    >
      <OfferQuotesStyle>
        <Tabs
          data={OFFER_QUOTES_TABS}
          onClick={handleTabClick}
          defaultTab={OFFER_QUOTES_TABS[0]}
        />
        {
          (selectedTab.value === OFFER_QUOTES_TABS[0].value) && offlineQuoteDetailData.id && offlineQuoteDetailData.prov_maps.map(provider => (
            <QuotesCard
              key={provider.id}
              policyData={offlineQuoteDetailData?.policy_details}
              provider={provider}
              onAccept={() => handleToggleConfirmationModal(provider.id)}
              onViewOffer={() => handleShowOfferQuote(provider)}
            />
          ))
        }
        {
          (selectedTab.value === OFFER_QUOTES_TABS[1].value) && ((offlineQuoteDetailData?.policy_details?.reviewFormData) ? (
            <OfflinePolicyQuote
              pageConfig={pageConfig}
              policyData={offlineQuoteDetailData.policy_details}
            />)
            : (
              <OfflinePolicyContainer
                history={history}
                pageConfig={pageConfig}
                policyData={offlineQuoteDetailData.policy_details}
              />
            ))
        }
        {
          showConfirmation && (
            <ConfirmationModal
              showModal={showConfirmation}
              confirmText={LANG_STRINGS.haveYouReadAndAgreedOffer}
              modelTitle={LANG_STRINGS.confirmation}
              cancelText={LANG_STRINGS.no}
              agreeText={LANG_STRINGS.yes}
              onAgree={handleAgreeModal}
              onClose={handleToggleConfirmationModal}
            />
          )
        }
      </OfferQuotesStyle>
      <ShowSnackbar />
    </Container>
  )
}

export default OfflineOfferQuotesContainer
