import { MV_RENEWAL_FLOW } from '../../../../../constants/pkgCode'

export const getProtectionType = (type, isSameAgent = false) => {
  if (type === 'new-purchase') {
    return {
      title: 'Polis baru: Mobil baru',
      code: 'new-policy-new-car',
    }
  } else if (isSameAgent) {
    return {
      title: 'Perpanjangan Polis: Dengan provider yang sama',
      code: 'renew-policy-with-same-provider',
    }
  } else {
    return {
      title: 'Perpanjangan Polis: Dengan provider yang berbeda',
      code: 'renew-policy-with-different-provider',
    }
  }
}

export const getDisabledFields = (purchaseRenewFlow, orgIsExpired) => {
  switch (purchaseRenewFlow) {
    case MV_RENEWAL_FLOW.O2O:
      if (orgIsExpired === false)
        return [
          'coverage_period_start',
          'vehicle_type',
          'year',
          'brand',
          'model_code',
          'chasis_number',
        ]
      return ['vehicle_type', 'year', 'brand', 'model_code', 'chasis_number']
    case MV_RENEWAL_FLOW.EXISTING_CAR:
    case MV_RENEWAL_FLOW.SHORTCUT:
    default:
      return []
  }
}

export function mapLocationStateToFormState(locationState) {
  const {
    reference_id,
    policy_state,
    is_expired,
    coverage_period_start,
    coverage_period_end,
    ...vehicleData
  } = locationState?.vehicleData
  delete vehicleData.is_same_agent // Remove unnecessary data

  const formState = {
    ...vehicleData,
    purchase_type: locationState?.purchaseType,
    purchase_renew_flow: locationState?.purchaseRenewFlow,
    org_policy_ref_id: reference_id,
    org_policy_status: policy_state,
    org_is_expired: is_expired,
  }

  if (formState.org_is_expired === false) {
    formState.coverage_period_start = formatDate(
      coverage_period_end,
      'YYYY-MM-DD'
    )
    formState.coverage_period_end = formatDate(
      dateAdd(coverage_period_end, 1, 'year'),
      'YYYY-MM-DD'
    )
  }
  if (formState.plate_number || formState.back_plate) {
    formState.vehicle_plate_no = [
      formState.plate_number || '',
      formState.back_plate || '',
    ].join('')
  }
  if (formState.model_data) {
    formState.model = formState.model_data.model_code
    formState.model_name = formState.model_data.model_name
    formState.model_code = formState.model_data.model_code
    formState.variant = formState.model_data.variant_name
    formState.variant_code = formState.model_data.variant_code
    formState.variant_name = formState.model_data.variant_name
    formState.category_name = formState.model_data.category_name
    formState.ev_variant = formState.model_data.ev_variant
    formState.vehicle_sum_insured = formState.model_data?.price
  }
  if (formState.vehicle_sum_insured) {
    formState.additional_sum_insured = 0 // hardcode to 0
  }
  if (formState.year) {
    formState.year = Number(formState.year)
  }
  if (formState.customer_data) {
    formState.customer_name = formState.customer_data?.name
    formState.customer_phone_no = formState.customer_data?.mobile_no
    formState.customer_email = formState.customer_data?.email
  }
  return formState
}

export function mapCurrencyType(formState) {
  return {
    currency_label: formState?.currency_label,
    exchange_rate: formState?.exchange_rate,
    currency_symbol: formState?.currency_symbol,
  }
}

export const getDobFmt = (dob) => {
  return moment(dob, 'DD/MM/YYYY').format('YYYY-MM-DD')
}

export const splitKeys = (key) => {
  // used to split nested keys
  if (key.split('.').length > 1) {
    return key.split('.')[1]
  }
  return key
}

export const modifyKey = (that, key) => {
  if (key.split('.').length > 1) {
    const keys = key.split('.')
    const parentKey = keys[0]
    const childKey = keys[1]
    return that.current?.[parentKey]?.[childKey]
  }
  return that.current[key]
}

export const getRespectiveGuideData = (name) => {
  let imgContainer = ''
  let modalTitle = ''
  let btmTitle = ''
  switch (name) {
    case 'stnk_url':
      modalTitle = LANG_STRINGS.stnkPhotoGuide
      btmTitle = LANG_STRINGS.makeSureVehicleRegistrationPicClear
      imgContainer = (
        <SingleImgContainer
          title={LANG_STRINGS.stnkPhoto}
          imgUrl={STNK}
          titlePosition="up"
          titleAlign="start"
        />
      )
      break
    case 'ktp_url':
      modalTitle = LANG_STRINGS.ktpPhotoGuide
      btmTitle = LANG_STRINGS.makeSureKTPPhotoClear
      imgContainer = (
        <SingleImgContainer
          title={LANG_STRINGS.photoKTP}
          imgUrl={KTP_IMG}
          titlePosition="up"
          titleAlign="start"
        />
      )
      break
    case 'vehicle_photo':
      modalTitle = LANG_STRINGS.vehiclePhotoGuide
      btmTitle = LANG_STRINGS.makeSureCarPicClear
      imgContainer = <VehicleGuideImgs />
      break
    case 'npwp_url':
      modalTitle = LANG_STRINGS.npwpPhotoGuide
      btmTitle = LANG_STRINGS.makeSureNPWPPhotoClear
      imgContainer = (
        <SingleImgContainer
          title={LANG_STRINGS.photoNPWP}
          imgUrl={NPWP_IMG}
          titlePosition="up"
          titleAlign="start"
        />
      )
      break
    case 'previous_certificate_url':
      modalTitle = LANG_STRINGS.certificatePolicyGuide
      btmTitle = LANG_STRINGS.verifyThePolicyCertificate
      imgContainer = (
        <SingleImgContainer
          title=""
          imgUrl={CERTIFICATE_PREVIEW}
          titlePosition="up"
          titleAlign="start"
        />
      )
      break
    default:
      return null
  }

  return {
    imgContainer,
    modalTitle,
    btmTitle,
  }
}

export const getRelevantError = (type) => {
  switch (type) {
    case 'chasis_number':
      return ERROR_LANG.chassisValidationError
    case 'machine_number':
      return ERROR_LANG.machineNumberValidation
    default:
      return ''
  }
}
