import { get } from 'lodash'
import { useCallback, useMemo } from 'react'
import { DisplayFlexCCC, Row } from '../../../../../../../commonStyle/index.style'
import { CustomText } from '../../../../../../../components'
import ShowSnackbar from '../../../../../../../components/ShowNotification'
import { AgentColorPallette } from '../../../../../../../configs/colorPallete'
import { formatMoney, getConvertedCurrency } from '../../../../../../../helpers/utility'
import { SHARE } from '../../../../../../../images'
import { ERROR_LANG, LANG_STRINGS } from '../../../../../../../lang'
import { OfferCardStyle } from './index.style'

function QuotesCard ({
  provider = {}, policyData = {}, onAccept = () => {}, onViewOffer = () => {}
}) {
  const totalPremium = useMemo(() => {
    const premium = Number(get(provider, 'premium'))
    const discount = Number(get(policyData, 'discount', 0))
    const grossPremium = Number(get(policyData?.premium_details, 'gross_premium'))
    const adminFee = Number(get(policyData?.premium_details, 'admin_fee'))
    const stampDuty = Number(get(policyData?.premium_details, 'stamp_duty'))
    return (premium - (grossPremium * discount) / 100 + adminFee + stampDuty)
  }, [policyData, provider])

  const handleShare = useCallback(() => {
    if (navigator.share) {
      // Web Share API is supported
      navigator.share({
        title: LANG_STRINGS.share,
        text: provider.quotation_slip_url
      })
        .catch(console.error)
    } else if (window.PPBridge) {
      window.PPBridge.share(LANG_STRINGS.share, provider.quotation_slip_url)
    } else {
      // Fallback
      ShowSnackbar.error({
        visible: true,
        text: ERROR_LANG.shareOptionNotSupport
      })
    }
  }, [provider])

  return (
    <OfferCardStyle>
      <Row justify='space-between' align='stretch' className='offer-card-top-section'>
        <Row justify='space-between' align='center'>
          <DisplayFlexCCC className='quote-product-img'>
            <img src={policyData.isCoinsurance ? provider.provider_data.provider_data.logo_url : provider.provider_data.logo_url} alt='' />
          </DisplayFlexCCC>
          <CustomText color={AgentColorPallette.black} size='13px' weight={800}>
            {policyData.isCoinsurance ? provider.provider_data.provider_data.name : provider.provider_data.name}
          </CustomText>
        </Row>
        <DisplayFlexCCC className='share-icon' onClick={handleShare}>
          <img src={SHARE} alt='Share' />
        </DisplayFlexCCC>
      </Row>
      <CustomText
        className='offer-price'
        color={AgentColorPallette.black}
        weight={800}
        size='14px'
        bottom='0'
      >
        {
          policyData.currency_label === 'IDR'
            ? formatMoney(totalPremium, 0)
            : `${policyData.currency_symbol || 'Rp'} ${getConvertedCurrency(totalPremium, provider.currency_details?.rate || policyData.exchange_rate)}`
        }
      </CustomText>
      {provider?.issuance_sla_days && <CustomText
        className='offer-price'
        color={AgentColorPallette.black}
        weight={800}
        size='12px'
        bottom='0'
      >
        {
          `Jika penawaran disetujui, penerbitan polis akan diproses maksimal ${provider?.issuance_sla_days} hari kerja`
        }
      </CustomText>}
      <Row
        justify='space-between'
        align='stretch'
        className='offer-btn-section'
      >
        <CustomText
          className='offer-btn'
          color={AgentColorPallette.black}
          weight={800}
          size='14px'
          textAlign='center'
          onClick={() => onViewOffer(provider)}
        >
          {LANG_STRINGS.viewOffer}
        </CustomText>
        <div className='pipe-separator' />
        <CustomText
          className='offer-btn'
          color={AgentColorPallette.black}
          weight={800}
          size='14px'
          textAlign='center'
          onClick={() => onAccept(provider)}
        >
          {LANG_STRINGS.acceptOffer}
        </CustomText>
      </Row>
    </OfferCardStyle>
  )
}

export default QuotesCard
