import { useState, useCallback } from 'react'
import { Row } from '../../../../../../../commonStyle/index.style'
import { CustomText } from '../../../../../../../components'
import CollapsibleCard from '../../../../../../../components/CollapsibleCard'
import CustomCheckbox from '../../../../../../../components/CustomCheckbox'
import TitleEditHeading from '../../../../../../../components/TitleEditHeading'
import { AgentColorPallette } from '../../../../../../../configs/colorPallete'
import { LANG_STRINGS } from '../../../../../../../lang'
import { AddOnsStyleWrapper, InstantApprovalStyleWrapper, PolicyInfoStyle } from '../../container/index.style'
import { OfflinePolicyQuoteWrapper } from './index.style'
import BottomActionSheet from '../../../../../../../components/BottomActionSheet'
import { InstantTermsStyle } from '../../../../../../CommonContainer/OfflinePolicyContainer/index.style'
import { modifyKey } from '../../../OfflinePolicyForm/constant'
import PrintPolicyData from '../../../../../../CommonContainer/OfflinePolicyContainer/components/PrintPolicyData'
import OfflinePolicyAddonsData from '../../../../../../CommonContainer/OfflinePolicyContainer/components/OfflineAddonsData'
import VehicleModificationData from '../../../../../../CommonContainer/OfflinePolicyContainer/components/VehicleModificationData'
import PdfContainer from '../../../../../../../components/PdfContainer'
import PrintMultipleImage from '../PrintMultipleImage'
import { formatMoney } from '../../../../../../../helpers/utility'
import moment from 'moment'
import RenderLossRecordDetails from '../RenderLossRecordDetails'
function OfflinePolicyQuote ({ pageConfig = {}, policyData = {}, isTransactionDetail = false }) {
  const [checkedInstantApproval] = useState(pageConfig?.isOfflineOrderDetail ? policyData.instant_approve : (policyData.prov_maps?.length === 1))
  const [showInstantTerms, setInstantTerms] = useState(false)
  const handleShowTermsToggle = useCallback(() => {
    setInstantTerms(prevShow => !prevShow)
  }, [])
  const renderInstantApproval = () => {
    return (
      <InstantApprovalStyleWrapper>
        <Row
          align='center'
          justify='space-between'
          className='pad-12'
        >
          <CustomText
            color={AgentColorPallette.fontDarkerGrey}
            size='14px'
            weight={800}
          >
            {LANG_STRINGS.partnerApproval}
          </CustomText>
          <CustomCheckbox
            onChange={() => {}}
            name='instant_approval'
            disabled={pageConfig?.isOfflineOrderDetails}
            isChecked={checkedInstantApproval}
            color={AgentColorPallette.black}
          />
        </Row>
        <CustomText
          color={AgentColorPallette.blackGrey}
          className='instant-terms-body'
        >
          {LANG_STRINGS.iAgreeWith}
          <span className='offline-terms' onClick={handleShowTermsToggle}>&nbsp;{LANG_STRINGS.termsConditions}</span>
        </CustomText>
      </InstantApprovalStyleWrapper>
    )
  }

  const getProviderNames = (providers = [], isCoinsurance = false) => {
    const providerNames = providers.map(provider => isCoinsurance ? provider.provider_data.name : provider.name)
    return providerNames.join(', ')
  }

  const formattedData = useCallback((key, type) => {
    const keyData = modifyKey({ current: policyData }, key)

    if (['uploadFileButton']?.includes(type)) {
      return (
        keyData ? <PdfContainer url={keyData} /> : '-'
      )
    } else if (type === 'uploadImage') {
      return keyData ? <PrintMultipleImage data={keyData} /> : '-'
    } else if (key === 'prov_maps') {
      return getProviderNames(Object.values(policyData?.providerData || policyData?.prov_maps), policyData?.isCoinsurance)
    } else if (['auto_calculate', 'amount'].includes(type)) {
      const amount = keyData
      return formatMoney(amount, 0,
        policyData?.currency_symbol, policyData?.currency_symbol === 'Rp' ? ',' : '.',
        policyData?.currency_symbol === 'Rp' ? '.' : ',')
    } else if (type === 'date') {
      return moment(policyData[key]).format('DD MMM YYYY')
    } else if (type === 'lossRecord') {
      return <RenderLossRecordDetails data={policyData?.loss_record_doc} />
    } else if (key === 'survey_report') {
      const filesName = policyData[key]?.map(file => file.slice(file.lastIndexOf('/') + 1))
      return filesName.join(', ')
    }
    return typeof keyData !== 'object' ? keyData : '-'
  }, [policyData])

  const mapHardCopyData = (policyData) => {
    return {
      hard_copy_required: policyData.hard_copy_required,
      insurance_details: {
        hard_copy_address: policyData.hard_copy_address,
        hard_copy_details: {
          recipient_name: policyData.hard_copy_recipient,
          hard_copy_recipient_mobile: policyData.hard_copy_recipient_mobile
        }
      }
    }
  }

  const renderSection = () => {
    return Object.values(policyData?.reviewFormData)?.map((section, index) => (
      <div className='form-container' key={index}>
        <div className='review-form'>
          {!isTransactionDetail && (
            <TitleEditHeading
              title={section.page_heading}
            />
          )}
          {
            section?.section?.map((item, index) => {
              return item.section_data[0]?.displayLabel === LANG_STRINGS.printPolicy ? (
                <AddOnsStyleWrapper>
                  <PrintPolicyData policy={mapHardCopyData(policyData)} />
                </AddOnsStyleWrapper>
              ) : (item.section_data[0]?.displayLabel === LANG_STRINGS.packageAddons) ? (
                <AddOnsStyleWrapper>
                  <OfflinePolicyAddonsData policyData={policyData} />
                </AddOnsStyleWrapper>
              ) : (item.section_data[0]?.displayLabel === LANG_STRINGS.vehicleModification) ? (
                <VehicleModificationData
                  policyData={policyData}
                  hidePhotos
                />
              ) : (
                <CollapsibleCard
                  title={item.section_heading}
                  key={index}
                  isOpen
                >
                  {
                    item?.section_data?.map((sectionData, index) => {
                      return (
                        <PolicyInfoStyle
                          isBorder={(index + 1) !== item.section_data.length}
                          align='center'
                          display='block'
                          justify='space-between'
                          onClick={sectionData.onClick ? sectionData.onClick : () => {}}
                          key={index}
                          bgColor={sectionData.bgColor}
                        >
                          <CustomText color={AgentColorPallette.fontDarkerGrey}>
                            {sectionData?.displayLabel}
                          </CustomText>
                          <CustomText
                            className='break-word-newline'
                            color={sectionData.color || AgentColorPallette.darkCharcoal}
                            weight={800}
                          >
                            {formattedData(sectionData.name, sectionData.type) || '-'}
                          </CustomText>
                        </PolicyInfoStyle>
                      )
                    })
                  }
                </CollapsibleCard>
              )
            })
          }
        </div>
        {!isTransactionDetail && (
          <div className='separator' />
        )}
      </div>
    ))
  }
  return (
    <OfflinePolicyQuoteWrapper isTransactionDetail>
      {renderSection()}
      {!isTransactionDetail && renderInstantApproval()}
      <BottomActionSheet
        show={showInstantTerms}
        onCloseSheet={handleShowTermsToggle}
      >
        <InstantTermsStyle>
          <Row justify='space-between' className='instant-terms-header'>
            <CustomText
              size='13px'
              weight='800'
              className='item-padding'
              color={AgentColorPallette.fontDarkerGrey}
            >
              {LANG_STRINGS.termsConditions}
            </CustomText>
            <CustomText
              size='15px'
              weight='800'
              className='item-padding'
              color={AgentColorPallette.fontDarkerGrey}
              onClick={handleShowTermsToggle}
            >
              X
            </CustomText>
          </Row>
          <CustomText
            size='1em'
            color={AgentColorPallette.blackGrey}
            className='bg-white'
            padLeft='12px'
            padRight='12px'
            padBottom='12px'
            top='12px'
          >
            {LANG_STRINGS.byCheckingThisYouAcceptTheOffers}
          </CustomText>
        </InstantTermsStyle>
      </BottomActionSheet>
    </OfflinePolicyQuoteWrapper>
  )
}

export default OfflinePolicyQuote
